package com.example.projetomarvel;
import android.app.Activity;import android.content.Intent;import android.os.SystemClock;import android.view.*;import android.widget.*;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.runner.lifecycle.*;
import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.io.*;import java.lang.reflect.*;
import static org.junit.Assert.*;import static com.example.projetomarvel.WorldValues.*;
import static androidx.test.espresso.Espresso.onView;import static androidx.test.espresso.matcher.ViewMatchers.withText;import static androidx.test.espresso.action.ViewActions.click;
/** Executes native creation, touch exploration and the existing real battle/result route. */
@RunWith(AndroidJUnit4.class) public class VisitWorldFlowTest {
 Map<String,Object>fixtures;
 @Before public void setup()throws Exception{VisitWorldActivity.activeSession=null;VisitWorldActivity.ecoMemory=null;ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream i=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("world-device-fixtures.json")){byte[]a=new byte[8192];int n;while((n=i.read(a))!=-1)b.write(a,0,n);}fixtures=map(WorldJson.parse(b.toString("UTF-8")));}
 ActivityScenario<VisitWorldActivity> open(){return ActivityScenario.launch(new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),VisitWorldActivity.class));}
 Map<String,Object>copy(Object o){return map(WorldJson.parse(WorldJson.write(o)));}
 View find(View root,String value){if(root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=find(((ViewGroup)root).getChildAt(i),value);if(v!=null)return v;}return null;}
 EditText input(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText e=input(((ViewGroup)v).getChildAt(i));if(e!=null)return e;}return null;}
 @Test public void storyButtonOpensNativeCreation(){try(ActivityScenario<MainActivity> sc=ActivityScenario.launch(new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),MainActivity.class))){sc.onActivity(a->a.open("História"));onView(withText("VISITAR MUNDO")).perform(click());InstrumentationRegistry.getInstrumentation().waitForIdleSync();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{boolean found=false;for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof VisitWorldActivity){VisitWorldActivity v=(VisitWorldActivity)a;assertTrue(v.creating);assertEquals(0,v.creationStep);found=true;v.exit();}assertTrue(found);});}}
 @Test public void customFourStepsTouchCollisionCameraAndFreshSession(){try(ActivityScenario<VisitWorldActivity> sc=open()){
  sc.onActivity(a->{assertTrue(a.creating);assertFalse(a.next.isEnabled());find(a.overlay,"Personagem Marvel").performClick();assertNull(find(a.overlay,"Deadpool"));find(a.overlay,"Meu personagem").performClick();input(a.overlay).setText("Explorador");assertTrue(a.next.isEnabled());a.next.performClick();assertEquals(1,a.creationStep);a.draft.put("skin",2);a.draft.put("build",2);a.draft.put("hair",1);a.next.performClick();assertEquals(2,a.creationStep);a.draft.put("color",2);a.next.performClick();assertEquals(3,a.creationStep);a.draft.put("power",5);a.next.performClick();assertFalse(a.creating);assertEquals("Explorador",get(a.session.get("character"),"name"));assertEquals("Telecinese",get(a.session.get("character"),"power"));assertEquals(2,integer(get(get(a.session.get("character"),"appearance"),"skin")));assertEquals(2,integer(get(get(a.session.get("character"),"appearance"),"build")));
   View up=find(a.hud,"▲");assertNotNull(up);assertTrue(up.getLayoutParams().width>=a.d(60));long t=SystemClock.uptimeMillis();up.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,20,20,0));assertTrue(a.held.containsValue("up"));double before=number(a.player().get("y"));float camera=a.world.cameraY;for(int n=0;n<40;n++)a.frame(.025f,t+n*25);assertTrue(number(a.player().get("y"))<before);assertNotEquals(camera,a.world.cameraY,.01f);up.dispatchTouchEvent(MotionEvent.obtain(t,t+1000,MotionEvent.ACTION_UP,20,20,0));assertTrue(a.held.isEmpty());
   assertFalse(a.world.walkable(0,0,8,a.flags(),a.visible(a.actors),null));Object solid=a.world.solids.get(0);assertFalse(a.world.walkable(number(get(solid,"x"))+2,number(get(solid,"y"))+2,8,a.flags(),arr(),null));a.save();assertNotNull(VisitWorldActivity.activeSession);a.exit();assertNull(VisitWorldActivity.activeSession);
  });}try(ActivityScenario<VisitWorldActivity> sc=open()){sc.onActivity(a->{assertTrue(a.creating);assertEquals(0,a.creationStep);assertEquals("",a.draft.get("name"));});}}
 @Test public void nearNpcTouchOpensDialogueWithTwoChoices(){try(ActivityScenario<VisitWorldActivity> sc=open()){sc.onActivity(a->{a.enter(copy(fixtures.get("custom-generic")),false);Object npc=a.actors.stream().filter(n->equal(get(n,"id"),"venom")).findFirst().get();a.player().put("x",number(get(npc,"px")));a.player().put("y",number(get(npc,"py"))+32);a.world.cameraReady=false;a.world.camera(a.player(),a.worldView.logicalWidth(),a.worldView.logicalHeight(),.05f);a.updateNearest(a.visible(a.actors));assertEquals(npc,a.nearest);assertFalse(a.dialogueOpen);float x=(float)(number(get(npc,"px"))-a.world.cameraX)*a.worldView.zoom(),y=(float)(number(get(npc,"py"))-15-a.world.cameraY)*a.worldView.zoom();long t=SystemClock.uptimeMillis();a.worldView.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0));assertTrue(a.dialogueOpen);assertEquals("venom",a.speaker.get("id"));assertNull(a.script.get("encounter"));a.onBackPressed();Object marcus=a.actors.stream().filter(n->equal(get(n,"id"),"marcus")).findFirst().get();a.openConversation(map(marcus));for(Object line:list(a.script.get("lines")))if(get(line,"options")!=null)assertEquals(2,list(get(line,"options")).size());});}}
 @Test public void realBattleRequestsAndVictoryReturn()throws Exception{
  String[]names={"custom-generic","hero-generic","hero-hero","hero-villain","hero-variant"};String[]ids={"station-guard","osc-guards","defender","doom","defender"};
  for(int index=0;index<names.length;index++){final int n=index;try(ActivityScenario<VisitWorldActivity> sc=open()){
   sc.onActivity(a->{a.enter(copy(fixtures.get(names[n])),false);Object npc=a.actors.stream().filter(v->equal(get(v,"id"),ids[n])).findFirst().get();a.showEncounter(map(npc));});onView(withText("Ir para a luta")).perform(click());
   InstrumentationRegistry.getInstrumentation().waitForIdleSync();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{FightActivity fight=resumedFight();Field engine=FightActivity.class.getDeclaredField("battle");engine.setAccessible(true);BattleEngine b=(BattleEngine)engine.get(fight);assertNotNull(b);assertEquals(n<=1?BattleEngine.Skill.GENERIC:n==3?BattleEngine.Skill.DOOM:BattleEngine.Skill.IRON,b.bot.skill);assertEquals(n==0,b.player.custom);if(n==4)assertTrue(fight.getIntent().getStringExtra("world_bot_label").contains("outra realidade"));b.player.x=350;b.bot.x=435;for(int step=0;step<8000&&!b.over;step++){b.attack(b.player,0);b.step(.01f,1,false,false);}assertTrue(b.over&&b.victory);Method finished=FightActivity.class.getDeclaredMethod("finishFight",boolean.class);finished.setAccessible(true);finished.invoke(fight,true);}catch(Exception e){throw new AssertionError(e);}});
   SystemClock.sleep(1400);onView(withText("Voltar ao mundo")).perform(click());sc.onActivity(a->{assertFalse(a.battlePending);assertTrue(truth(get(a.session.get("encounters"),ids[n])));assertFalse(truth(a.rules.run("encounterAllowed",a.session,ids[n])));a.exit();});
  }}
 }
 @Test public void defeatAndCancelKeepEncounterAvailable()throws Exception{try(ActivityScenario<VisitWorldActivity> sc=open()){
  sc.onActivity(a->{a.enter(copy(fixtures.get("custom-generic")),false);Object npc=a.actors.stream().filter(v->equal(get(v,"id"),"station-guard")).findFirst().get();a.showEncounter(map(npc));});onView(withText("Ir para a luta")).perform(click());InstrumentationRegistry.getInstrumentation().waitForIdleSync();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{try{FightActivity f=resumedFight();Field field=FightActivity.class.getDeclaredField("battle");field.setAccessible(true);BattleEngine b=(BattleEngine)field.get(f);b.player.x=350;b.bot.x=415;for(int tick=0;tick<8000&&!b.over;tick++){b.player.x=350;b.bot.x=415;b.attack(b.bot,0);b.step(.01f,0,false,false);}assertTrue(b.over&&!b.victory);Method ended=FightActivity.class.getDeclaredMethod("finishFight",boolean.class);ended.setAccessible(true);ended.invoke(f,false);}catch(Exception e){throw new AssertionError(e);}});SystemClock.sleep(1400);onView(withText("Voltar ao mundo")).perform(click());sc.onActivity(a->{assertFalse(a.battlePending);assertFalse(truth(get(a.session.get("encounters"),"station-guard")));assertTrue(truth(a.rules.run("encounterAllowed",a.session,"station-guard")));Object npc=a.actors.stream().filter(v->equal(get(v,"id"),"station-guard")).findFirst().get();a.showEncounter(map(npc));});onView(withText("Ir para a luta")).perform(click());InstrumentationRegistry.getInstrumentation().waitForIdleSync();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->resumedFight().onBackPressed());sc.onActivity(a->{assertFalse(a.battlePending);assertFalse(truth(get(a.session.get("encounters"),"station-guard")));assertTrue(truth(a.rules.run("encounterAllowed",a.session,"station-guard")));});
 }}
 FightActivity resumedFight(){for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof FightActivity)return (FightActivity)a;throw new AssertionError("Existing battle did not open");}
}
